"""Validate generated 0.8 documents. SVG technical plans are not screenshots."""
from pathlib import Path
import json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1];checks=[];errors=[]
def ck(name,ok):checks.append(dict(name=name,ok=bool(ok)));print(('PASS 'if ok else 'FAIL ')+name,flush=True)
C=json.loads((R/'src/content.json').read_text());M=json.loads((R/'docs/METRIQUES.json').read_text())
with sync_playwright() as w:
 b=w.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);p=b.new_page(viewport=dict(width=1440,height=1000));p.on('pageerror',lambda e:errors.append(str(e)));p.set_default_timeout(6000)
 p.set_content((R/'docs/CODEX_ISOLATION.html').read_text(),wait_until='load')
